import React, { useState, useEffect } from "react";
import api from "../api";
import io from "socket.io-client";

type Comment = {
  _id: string;
  body: string;
  createdAt: string;
  author?: {
    firstName?: string;
    lastName?: string;
    email?: string;
  };
};

type Ticket = {
  _id: string;
  title: string;
  description?: string;
  category: "Billing" | "Technical" | "General";
  status: string;
  priority: string;
  createdBy: string;
  assignee?: string | null;
  createdAt: string;
  comments?: Comment[];
};

const UserDashboard: React.FC<{ name: string }> = ({ name }) => {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const [myTickets, setMyTickets] = useState<Ticket[]>([]);
  const [selectedTicket, setSelectedTicket] = useState<Ticket | null>(null);

  // Inline editing states
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [isEditingDescription, setIsEditingDescription] = useState(false);

  const [editTitle, setEditTitle] = useState("");
  const [editDescription, setEditDescription] = useState("");

  // Comment state
  const [newComment, setNewComment] = useState("");
  const [isAddingComment, setIsAddingComment] = useState(false);

  const [socket, setSocket] = useState<any>(null);

  const handleCreateTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage("");

    try {
      await api.post("/tickets", {
        title,
        description,
        category,
      });

      setMessage("Ticket created successfully!");
      setTitle("");
      setDescription("");
      setCategory("");

      fetchTickets();
    } catch (err: any) {
      console.error(err);
      const msg = err?.response?.data?.message || "Something went wrong";
      setError(msg);
    }
  };

  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setMyTickets(res.data);
    } catch (err: any) {
      console.error(err);
      const msg = err?.response?.data?.message || "Failed to fetch tickets";
      setError(msg);
    }
  };

  const deleteTicket = async (id: string) => {
    try {
      await api.delete(`/tickets/${id}`);

      setMyTickets((prev) => prev.filter((t) => t._id !== id));

      if (selectedTicket?._id === id) {
        setSelectedTicket(null);
      }
    } catch (err: any) {
      console.error(err);
      const msg = err?.response?.data?.message || "Failed to delete ticket";
      setError(msg);
    }
  };

  // Save TITLE only
  const saveTitle = async () => {
    if (!selectedTicket) return;

    try {
      const res = await api.patch(`/tickets/${selectedTicket._id}`, {
        title: editTitle,
      });

      const updated = res.data as Ticket;

      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );

      setSelectedTicket(updated);
      setIsEditingTitle(false);
    } catch (err: any) {
      console.error(err);
      const msg = err?.response?.data?.message || "Failed to update title";
      setError(msg);
    }
  };

  // Save DESCRIPTION only
  const saveDescription = async () => {
    if (!selectedTicket) return;

    try {
      const res = await api.patch(`/tickets/${selectedTicket._id}`, {
        description: editDescription,
      });

      const updated = res.data as Ticket;

      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );

      setSelectedTicket(updated);
      setIsEditingDescription(false);
    } catch (err: any) {
      console.error(err);
      const msg =
        err?.response?.data?.message || "Failed to update description";
      setError(msg);
    }
  };

  const addComment = async () => {
    if (!selectedTicket) return;
    const trimmed = newComment.trim();
    if (!trimmed) return;

    try {
      setIsAddingComment(true);
      setError("");

      const res = await api.post(`/tickets/${selectedTicket._id}/comments`, {
        body: trimmed,
      });

      const updated = res.data as Ticket;

      // update list
      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );

      // update selected
      setSelectedTicket(updated);

      // clear input
      setNewComment("");
    } catch (err: any) {
      console.error("Add comment error", err);
      const msg = err?.response?.data?.message || "Failed to add comment";
      setError(msg);
    } finally {
      setIsAddingComment(false);
    }
  };

  useEffect(() => {
    fetchTickets();
  }, []);

  useEffect(() => {
    const s = io("http://localhost:5050", {
      withCredentials: true,
    } as any);

    setSocket(s);

    return () => {
      s.disconnect();
    };
  }, []);

  useEffect(() => {
    if (!socket) return;

    const refresh = () => {
      fetchTickets();
    };

    socket.on("ticketUpdated", refresh);
    socket.on("ticketDeleted", refresh);

    return () => {
      socket.off("ticketUpdated", refresh);
      socket.off("ticketDeleted", refresh);
    };
  }, [socket]);

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Welcome, {name}!</p>

      <h3>Create Ticket</h3>

      <form onSubmit={handleCreateTicket}>
        <input
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />

        <br />

        <textarea
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />

        <br />

        <select value={category} onChange={(e) => setCategory(e.target.value)}>
          <option value="">Select Category</option>
          <option value="Technical">Technical</option>
          <option value="Billing">Billing</option>
          <option value="General">General</option>
        </select>

        <button type="submit">Create Ticket</button>
      </form>

      {error && <p style={{ color: "red" }}>{error}</p>}
      {message && !error && <p>{message}</p>}

      <h3>My Tickets</h3>

      {myTickets.length === 0 ? (
        <p>No tickets yet.</p>
      ) : (
        <ul>
          {myTickets.map((t) => (
            <li
              key={t._id}
              style={{ cursor: "pointer" }}
              onClick={() => {
                setSelectedTicket(t);
                setEditTitle(t.title);
                setEditDescription(t.description || "");
                setIsEditingTitle(false);
                setIsEditingDescription(false);
                setNewComment("");
              }}
            >
              {t.title}
            </li>
          ))}
        </ul>
      )}

      {selectedTicket && (
        <div style={{ marginTop: "20px" }}>
          <h3>Ticket Details</h3>

          {/* TITLE */}
          <p>
            <strong>Title:</strong>{" "}
            {!isEditingTitle ? (
              <>
                {selectedTicket.title}
                <button
                  style={{ marginLeft: "10px" }}
                  onClick={() => setIsEditingTitle(true)}
                >
                  Edit
                </button>
              </>
            ) : (
              <>
                <input
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  style={{ width: "300px" }}
                />
                <button style={{ marginLeft: "10px" }} onClick={saveTitle}>
                  Save
                </button>
                <button
                  style={{ marginLeft: "5px" }}
                  onClick={() => {
                    setEditTitle(selectedTicket.title);
                    setIsEditingTitle(false);
                  }}
                >
                  Cancel
                </button>
              </>
            )}
          </p>

          {/* DESCRIPTION */}
          <p>
            <strong>Description:</strong>{" "}
            {!isEditingDescription ? (
              <>
                {selectedTicket.description}
                <button
                  style={{ marginLeft: "10px" }}
                  onClick={() => setIsEditingDescription(true)}
                >
                  Edit
                </button>
              </>
            ) : (
              <>
                <textarea
                  value={editDescription}
                  onChange={(e) => setEditDescription(e.target.value)}
                  rows={3}
                  style={{ width: "300px" }}
                />
                <button
                  style={{ marginLeft: "10px" }}
                  onClick={saveDescription}
                >
                  Save
                </button>
                <button
                  style={{ marginLeft: "5px" }}
                  onClick={() => {
                    setEditDescription(selectedTicket.description || "");
                    setIsEditingDescription(false);
                  }}
                >
                  Cancel
                </button>
              </>
            )}
          </p>

          <p>
            <strong>Category:</strong> {selectedTicket.category}
          </p>
          <p>
            <strong>Status:</strong> {selectedTicket.status}
          </p>
          <p>
            <strong>Priority:</strong> {selectedTicket.priority}
          </p>
          <p>
            <strong>Created:</strong>{" "}
            {new Date(selectedTicket.createdAt).toLocaleString()}
          </p>
          {/* ======================= COMMENTS ======================= */}
          <div style={{ marginTop: "20px" }}>
            <h4>Comments</h4>

            {/* Existing comments */}
            {selectedTicket.comments && selectedTicket.comments.length > 0 ? (
              <ul>
                {selectedTicket.comments.map((c: any) => (
                  <li key={c._id} style={{ marginBottom: "10px" }}>
                    <strong>{c.author?.email || "Unknown user"}:</strong>
                    <p style={{ margin: "3px 0" }}>{c.body}</p>
                    <small>{new Date(c.createdAt).toLocaleString()}</small>
                  </li>
                ))}
              </ul>
            ) : (
              <p>No comments yet.</p>
            )}

            {/* Add new comment */}
            <textarea
              placeholder="Write a comment..."
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              rows={3}
              style={{ width: "300px", marginTop: "10px" }}
            />

            <br />

            <button
              onClick={addComment}
              disabled={isAddingComment}
              style={{ marginTop: "10px" }}
            >
              {isAddingComment ? "Posting..." : "Add Comment"}
            </button>
          </div>
          {/* ======================================================== */}
          <br />
          <button
            onClick={() => deleteTicket(selectedTicket._id)}
            style={{ marginRight: "10px", color: "red" }}
          >
            Delete Ticket
          </button>

          <button onClick={() => setSelectedTicket(null)}>Close</button>
        </div>
      )}
    </div>
  );
};

export default UserDashboard;
